/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountDotMatrixTrio, type DotMatrixTrioOptions } from "../../components/dot-matrix-trio/DotMatrixTrioEngine.js";
import type { MotionController } from "../../components/dot-matrix-trio/motion-runtime";

export function DotMatrixTrio(props: { options?: DotMatrixTrioOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountDotMatrixTrio(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="dot-matrix-trio" />;
}

